css:
body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11px;
    color: #000;
}

.company-header {
    margin-bottom: 5px;
}

.company-name {
    font-size: 16px;
    font-weight: bold;
    text-transform: uppercase;
    text-align: left;
    margin-bottom: 5px;
}

.company-address {
    margin-top: 5px;
    line-height: 1.5;
}

.party-section {
    width: 100%;
    margin-top: 5px;
    margin-bottom: 5px;
}

.party-left {
    float: left;
    width: 70%;
}

.party-right {
    float: right;
    width: 25%;
    text-align: right;
}

.clearfix {
    clear: both;
}

.separator {
    border-top: 1px solid #000;
    margin: 5px 0;
}
.details-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0px !important;
    margin-bottom: 0px !important;
}

.details-table td {
    padding: 0px !important;
    line-height: 1.1 !important;
    vertical-align: top;
    border: none !important;
    color:#222;
}

.details-table tr {
    height: 16px !important;
}

.label {
    width: 170px;
    font-weight: bold;
    white-space: nowrap;
}

.value {
    padding-left: 0;
}

.label {
    width: 180px;
    font-weight: bold;
    white-space: nowrap;
    border: none !important;
    padding-right: 10px;
}

.section-title {
    font-weight: bold;
    text-decoration: underline;
    margin-top: 0px !important;
    margin-bottom: 2px !important;
    padding: 0px !important;
}

.adjustment-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    margin-top: 10px;
    font-size: 13px;
}

.adjustment-table th,
.adjustment-table td {
    border: 1px solid #000 !important;
    padding: 1px 3px !important;
    line-height: 1.0 !important;
}

.adjustment-table tr {
    border: 1px solid #000 !important;
}

.adjustment-table tbody tr {
    border-bottom: 1px solid #000 !important;
}

.adjustment-table th {
    text-align: center;
    font-weight: bold;
    background: #f5f5f5;
}

.adjustment-table td {
    vertical-align: middle;
}
.company-header,
.party-section,
.details-table,
.section-title {
    font-size: 13px;
}
.adjustment-table table,
.adjustment-table tr,
.adjustment-table td,
.adjustment-table th {
    border-collapse: collapse !important;
}
.print-format {
    padding: 12px !important;
    margin: 0 !important;
}

p {
    margin: 0;
}

table {
    margin-bottom: 0;
}
.details-table + .section-title {
    margin-top: 0px !important;
}

.print-format p,
.print-format div,
.print-format table {
    margin-bottom: 0px !important;
}
.adjustment-table {
    border-collapse: collapse !important;
    border-spacing: 0 !important;
}

.adjustment-table tr {
    height: 18px !important;
}

.adjustment-table td {
    margin: 0 !important;
}

.adjustment-table th {
    margin: 0 !important;
}

html:
{# ============================================================
   COMPANY DETAILS
   ============================================================ #}

{% set company_doc = frappe.get_doc("Company", doc.company) %}

{# Find Company Address directly from Address Dynamic Link #}

{% set company_addresses = frappe.get_all(
    "Address",
    filters={
        "name": [
            "in",
            frappe.get_all(
                "Dynamic Link",
                filters={
                    "link_doctype": "Company",
                    "link_name": doc.company
                },
                pluck="parent"
            )
        ]
    },
    fields=[
        "name",
        "address_line1",
        "address_line2",
        "city",
        "state",
        "pincode",
        "country"
    ],
    limit=1
) %}

{% set company_address = None %}

{% if company_addresses %}
    {% set company_address = company_addresses[0] %}
{% endif %}


<div class="company-name">
    {{ company_doc.company_name }}
</div>


<div class="company-address">

    {% if company_address %}

        {% if company_address.address_line1 %}
            {{ company_address.address_line1 }}
        {% endif %}

        {% if company_address.address_line2 %}
            , {{ company_address.address_line2 }}
        {% endif %}

        {% if company_address.city %}
            , {{ company_address.city }}
        {% endif %}

        {% if company_address.state %}
            , {{ company_address.state }}
        {% endif %}

        {% if company_address.pincode %}
            - {{ company_address.pincode }}
        {% endif %}

        {% if company_address.country %}
            , {{ company_address.country }}
        {% endif %}

    {% endif %}

</div>


{# ============================================================
   PARTY DETAILS
   ============================================================ #}

<div class="party-section">

    <div class="party-left">

        <b>To,</b><br>


        {# ----------------------------------------------------
           Find Party Address
           Payment Entry Party = Supplier
           ---------------------------------------------------- #}

        {% set party_address_names = frappe.get_all(
            "Dynamic Link",
            filters={
                "link_doctype": doc.party_type,
                "link_name": doc.party
            },
            pluck="parent"
        ) %}


        {% set party_addresses = frappe.get_all(
            "Address",
            filters={
                "name": [
                    "in",
                    party_address_names
                ]
            },
            fields=[
                "name",
                "address_line1",
                "address_line2",
                "city",
                "state",
                "pincode",
                "country"
            ],
            limit=1
        ) %}


        {% set party_address = None %}

        {% if party_addresses %}
            {% set party_address = party_addresses[0] %}
        {% endif %}


        <b>{{ doc.party_name or doc.party }}</b><br>


        {# ----------------------------------------------------
           Party Address
           ---------------------------------------------------- #}

        {% if party_address %}

            {% if party_address.address_line1 %}
                {{ party_address.address_line1 }}
            {% endif %}

            {% if party_address.address_line2 %}
                , {{ party_address.address_line2 }}
            {% endif %}

            <br>

            {% if party_address.city %}
                {{ party_address.city }}
            {% endif %}

            {% if party_address.state %}
                , {{ party_address.state }}
            {% endif %}

            {% if party_address.pincode %}
                - {{ party_address.pincode }}
            {% endif %}

            {% if party_address.country %}
                , {{ party_address.country }}
            {% endif %}

        {% endif %}

    </div>


    <div class="party-right">

        <b>Date :</b>

        {{ frappe.utils.formatdate(
            doc.posting_date,
            "dd-mm-yyyy"
        ) }}

    </div>

</div>


<div class="clearfix"></div>

<div class="separator"></div>

<br>


{# ============================================================
   PAYMENT DETAILS
   ============================================================ #}

<table class="details-table">

<tr>
    <td><b>Bank Name :</b></td>
    <td>{{ doc.paid_from }}</td>
</tr>


<tr>
    <td><b>Cheque No :</b></td>
    <td>{{ doc.reference_no }}</td>
</tr>


<tr>
    <td><b>Cheque Date :</b></td>
    <td>
        {{ frappe.utils.formatdate(doc.reference_date) }}
    </td>
</tr>


<tr>
    <td><b>Cheque Amount :</b></td>
    <td>{{ doc.paid_amount }}</td>
</tr>


<tr>
    <td><b>Amount In Words :</b></td>
    <td>{{ doc.base_in_words }}</td>
</tr>


<tr>
    <td><b>Reference :</b></td>

    <td>
        {{ doc.name }}
        &nbsp;&nbsp;&nbsp;&nbsp;
        Dated:
        {{ frappe.utils.formatdate(doc.posting_date) }}
    </td>
</tr>


<tr>
    <td><b>Remarks :</b></td>
    <td></td>
</tr>

</table>


<br>
{# ============================================================
   CLEARING ADJUSTMENTS
   ============================================================ #}

<div class="section-title">
    Clearing Adjustments :
</div>

<div style="height:8px;"></div>

{% set ns = namespace(idx=0) %}
{% set detail = {} %}
{% set shown = [] %}

{# ================= PRE-PASS: har PI ka difference todna ================= #}
{% for r in doc.references %}
    {% if r.reference_doctype == "Purchase Invoice"
          and not frappe.db.get_value("Purchase Invoice", r.reference_name, "is_return")
          and (frappe.utils.flt(r.total_amount) - frappe.utils.flt(r.allocated_amount))|abs > 0.01 %}

        {% set gap = namespace(v = frappe.utils.flt(r.total_amount) - frappe.utils.flt(r.allocated_amount)) %}
        {% set rts = [] %}
        {% set pays = [] %}
        {% set jvs = [] %}
        {% set names = [] %}

        {# ---- 1) System generated JE ke Accounts table se RT ---- #}
        {% set je_rows = frappe.db.sql("""
            SELECT
                rpi.name, rpi.posting_date, rpi.bill_no, rpi.bill_date,
                SUM(IFNULL(b.debit, 0) + IFNULL(b.credit, 0)) AS je_amt
            FROM `tabJournal Entry Account` a
            INNER JOIN `tabJournal Entry` j ON j.name = a.parent
            INNER JOIN `tabJournal Entry Account` b ON b.parent = a.parent
            INNER JOIN `tabPurchase Invoice` rpi ON rpi.name = b.reference_name
            WHERE a.reference_type = 'Purchase Invoice'
              AND a.reference_name = %(pi)s
              AND j.docstatus = 1
              AND IFNULL(j.is_system_generated, 0) = 1
              AND b.reference_type = 'Purchase Invoice'
              AND b.reference_name != %(pi)s
              AND rpi.is_return = 1
              AND rpi.docstatus = 1
            GROUP BY rpi.name, rpi.posting_date, rpi.bill_no, rpi.bill_date
            ORDER BY rpi.posting_date, rpi.name
        """, {"pi": r.reference_name}, as_dict=1) %}

        {% for rt in je_rows %}
            {% set amt = frappe.utils.flt(rt.je_amt) | abs %}
            {% set _ = names.append(rt.name) %}
            {% set _ = shown.append(rt.name) %}
            {% set _ = rts.append({"name": rt.name, "date": rt.posting_date, "bill_no": rt.bill_no, "bill_date": rt.bill_date, "amt": amt}) %}
            {% set gap.v = gap.v - amt %}
        {% endfor %}

        {# ---- 2) Manual Discount JV (system generated nahi) ---- #}
        {% set jv_rows = frappe.db.sql("""
            SELECT
                j.name AS jv_name,
                j.posting_date AS jv_date,
                SUM(p.debit) AS discount_amt
            FROM `tabJournal Entry Account` p
            INNER JOIN `tabJournal Entry` j ON j.name = p.parent
            WHERE p.reference_type = 'Purchase Invoice'
              AND p.reference_name = %(pi)s
              AND p.party = %(party)s
              AND j.docstatus = 1
              AND IFNULL(j.is_system_generated, 0) = 0
              AND IFNULL(j.voucher_type, '') NOT IN ('Exchange Gain Or Loss', 'Exchange Rate Revaluation')
              AND p.debit > 0
            GROUP BY j.name, j.posting_date
            ORDER BY j.posting_date
        """, {"pi": r.reference_name, "party": doc.party}, as_dict=1) %}

        {% for d in jv_rows %}
            {% set amt = frappe.utils.flt(d.discount_amt) %}
            {% set _ = jvs.append({"name": d.jv_name, "date": d.jv_date, "amt": amt}) %}
            {% set gap.v = gap.v - amt %}
        {% endfor %}

        {# ---- 3) FALLBACK: abhi bhi gap bacha hai to seedha RT dhundo ---- #}
        {% if gap.v > 0.01 %}

            {% set fb_rt = frappe.db.sql("""
                SELECT DISTINCT
                    rpi.name, rpi.posting_date, rpi.bill_no, rpi.bill_date, rpi.grand_total
                FROM `tabPurchase Invoice` rpi
                WHERE rpi.docstatus = 1
                  AND rpi.is_return = 1
                  AND (
                        rpi.return_against = %(pi)s
                        OR rpi.name IN (
                            SELECT ple.voucher_no
                            FROM `tabPayment Ledger Entry` ple
                            WHERE ple.voucher_type = 'Purchase Invoice'
                              AND ple.against_voucher_type = 'Purchase Invoice'
                              AND ple.against_voucher_no = %(pi)s
                              AND ple.voucher_no != ple.against_voucher_no
                              AND ple.delinked = 0
                        )
                        OR rpi.name IN (
                            SELECT pii.parent
                            FROM `tabPurchase Invoice Item` pii
                            WHERE pii.purchase_receipt IN (
                                SELECT prt.name
                                FROM `tabPurchase Receipt` prt
                                WHERE prt.docstatus = 1
                                  AND prt.is_return = 1
                                  AND prt.return_against IN (
                                        SELECT a.purchase_receipt
                                        FROM `tabPurchase Invoice Item` a
                                        WHERE a.parent = %(pi)s
                                          AND IFNULL(a.purchase_receipt, '') != ''
                                  )
                            )
                        )
                  )
                ORDER BY rpi.posting_date, rpi.name
            """, {"pi": r.reference_name}, as_dict=1) %}

            {% for rt in fb_rt %}
                {% if rt.name not in names and gap.v > 0.01 %}
                    {% set full = frappe.utils.flt(rt.grand_total) | abs %}
                    {% set amt = full if full < gap.v else gap.v %}
                    {% set _ = names.append(rt.name) %}
                    {% set _ = shown.append(rt.name) %}
                    {% set _ = rts.append({"name": rt.name, "date": rt.posting_date, "bill_no": rt.bill_no, "bill_date": rt.bill_date, "amt": amt}) %}
                    {% set gap.v = gap.v - amt %}
                {% endif %}
            {% endfor %}
        {% endif %}

        {# ---- 4) FALLBACK: pehle ki dusri Payment Entry ---- #}
        {% if gap.v > 0.01 %}
            {% set old_pe = frappe.db.sql("""
                SELECT pe.name, pe.posting_date, SUM(per.allocated_amount) AS amt
                FROM `tabPayment Entry Reference` per
                INNER JOIN `tabPayment Entry` pe ON pe.name = per.parent
                WHERE per.reference_doctype = 'Purchase Invoice'
                  AND per.reference_name = %(pi)s
                  AND pe.docstatus = 1
                  AND pe.name != %(pe)s
                GROUP BY pe.name, pe.posting_date
                ORDER BY pe.posting_date
            """, {"pi": r.reference_name, "pe": doc.name}, as_dict=1) %}

            {% for p in old_pe %}
                {% if gap.v > 0.01 %}
                    {% set full = frappe.utils.flt(p.amt) | abs %}
                    {% set amt = full if full < gap.v else gap.v %}
                    {% set _ = pays.append({"name": p.name, "date": p.posting_date, "amt": amt}) %}
                    {% set gap.v = gap.v - amt %}
                {% endif %}
            {% endfor %}
        {% endif %}

        {% set other = gap.v if gap.v > 0.01 else 0 %}

        {% set _ = detail.update({r.reference_name: {"rts": rts, "pays": pays, "jvs": jvs, "other": other}}) %}
    {% endif %}
{% endfor %}

{# ================= PRINT ================= #}
{% for ref in doc.references %}
{% if ref.reference_doctype == "Purchase Invoice" %}

    {% set pi = frappe.get_doc("Purchase Invoice", ref.reference_name) %}

    {# Jo RT parent PI ke neeche dikh rahi hai wo alag point me nahi aayegi #}
    {% if not (pi.is_return and ref.reference_name in shown) %}

        {% set ns.idx = ns.idx + 1 %}

        {% set payment_grand_total = frappe.utils.flt(ref.total_amount) %}
        {% set net_amount = frappe.utils.flt(ref.allocated_amount) %}

        {# ---------- TDS ---------- #}
        {% set tds_rows = frappe.db.sql("""
            SELECT COALESCE(SUM(tax_amount), 0) AS total_tds
            FROM `tabPurchase Taxes and Charges`
            WHERE parent = %s
              AND parenttype = 'Purchase Invoice'
              AND is_tax_withholding_account = 1
        """, (ref.reference_name,), as_dict=1) %}

        {% set total_tds = 0 %}
        {% if tds_rows %}
            {% set total_tds = frappe.utils.flt(tds_rows[0].total_tds) %}
        {% endif %}

        {% if total_tds > 0 %}
            {% set doc_amount = payment_grand_total + total_tds %}
        {% else %}
            {% set doc_amount = payment_grand_total %}
        {% endif %}

        {% set dt = detail.get(ref.reference_name, {}) %}
        {% set rts = dt.get("rts", []) %}
        {% set pays = dt.get("pays", []) %}
        {% set jvs = dt.get("jvs", []) %}
        {% set other = dt.get("other", 0) %}

        {% set rt_ns = namespace(total=0) %}
        {% for rt in rts %}
            {% set rt_ns.total = rt_ns.total + rt.amt %}
        {% endfor %}

        <div style="margin:0 0 4px 0; padding:0 0 0 20px; text-indent:-20px; line-height:1.4; page-break-inside:avoid;">

            {{ ns.idx }}. Against {{ ref.reference_name }}
            Dated: {{ frappe.utils.formatdate(pi.posting_date) }}
            (Doc No: {{ pi.bill_no or "" }}
            Doc Dt: {{ frappe.utils.formatdate(pi.bill_date) if pi.bill_date else "" }}
            Doc Amt: Rs. {{ "%.2f"|format(doc_amount) }})

            {% if total_tds > 0 %}
                Adjusted Amt: TDS Rs. {{ "%.2f"|format(total_tds) }}
            {% endif %}

            {% if rts %}
                {% if total_tds > 0 %}|{% endif %}
                Adjusted Amt: Rs. {{ "%.2f"|format(rt_ns.total) }}
                {% for rt in rts %}
                    (Against {{ rt.name }}
                    Dated: {{ frappe.utils.formatdate(rt.date) }}
                    {% if rt.bill_no %}Doc No: {{ rt.bill_no }}{% endif %}
                    {% if rt.bill_date %}Doc Dt: {{ frappe.utils.formatdate(rt.bill_date) }}{% endif %}
                    Amt: Rs. {{ "%.2f"|format(rt.amt) }})
                {% endfor %}
            {% endif %}

            {% for p in pays %}
                | Against {{ p.name }}
                Dated: {{ frappe.utils.formatdate(p.date) }}
                Earlier Payment: Rs. {{ "%.2f"|format(p.amt) }}
            {% endfor %}

            {% for d in jvs %}
                | Against {{ d.name }}
                Dated: {{ frappe.utils.formatdate(d.date) }}
                Discount Amt: Rs. {{ "%.2f"|format(d.amt) }}
            {% endfor %}

            {% if other > 0 %}
                | Other Adjustments: Rs. {{ "%.2f"|format(other) }}
            {% endif %}

            {% if total_tds > 0 or rts or pays or jvs or other > 0 %}|{% endif %}
            Net Amount: {{ "%.2f"|format(net_amount) }}

        </div>

    {% endif %}
{% endif %}
{% endfor %}
